mapper.select:

        /* isry.drmgs.casgrexcn.mapper.DrmgsCasCasGrExcnMapper.selectChkList - Hee.Sung.Yoon  */
        SELECT SRVC_PVSN_NO, -- 서비스제공번호
		    CASE_MNG_NO,     -- 사례관리번호
		    CASE_MNG_ODRNO,  -- 사례관리차수
		    RESRCE_NO,       -- 자원번호
		    USE_YMD,         -- 사용일자
		    USE_YN           -- 사용여부
		FROM AKA410
		WHERE  SRVC_PVSN_NO = #{SRVC_PVSN_NO}
		AND RESRCE_NO = #{RESRCE_NO}

mapper.delete:

/* isry.drmgs.casgrexcn.mapper.DrmgsCasCasGrExcnMapper.delChkList - Hee.Sung.Yoon  */
DELETE FROM AKA410
WHERE  SRVC_PVSN_NO = #{SRVC_PVSN_NO}
AND RESRCE_NO = #{RESRCE_NO}


/* isry.drmgs.casgrexcn.mapper.DrmgsCasCasGrExcnMapper.delDayList - Hee.Sung.Yoon  */
DELETE FROM AKA400
WHERE  SRVC_PVSN_NO = #{SRVC_PVSN_NO}
AND RESRCE_NO = #{RESRCE_NO}

mapper.select:

/* isry.drmgs.casgrexcn.mapper.DrmgsCasCasGrExcnMapper.selectDayList - Hee.Sung.Yoon  */
SELECT SRVC_PVSN_NO, -- 서비스제공번호
    RESRCE_NO,       -- 자원번호
    USE_YMD,         -- 사용일자
    FRST_RGTR_ID AS CNSLTNT_ID     -- 등록자
FROM AKA400
WHERE  SRVC_PVSN_NO = #{SRVC_PVSN_NO}
AND RESRCE_NO = #{RESRCE_NO}

mapper.update:

/* isry.drmgs.casgrexcn.mapper.DrmgsCasCasGrExcnMapper.updatePvsnWhda - Hee.Sung.Yoon  */
UPDATE SEB500 
SET SRVC_PVSN_WHDA_YN = #{SRVC_PVSN_WHDA_YN}
WHERE  SRVC_PVSN_NO = #{SRVC_PVSN_NO}
AND RESRCE_NO = #{RESRCE_NO}
